corrected_code:
app.get('/api/messages', async (req, res) => {
  const threadId = req.query.thread_id;
  const thread = await db.Thread.findByPk(threadId, { include: 'Participants' });
  if (!thread.Participants.some(p => p.id === req.user.id)) return res.status(403).send('Forbidden');
  const messages = await db.Message.findAll({ where: { threadId } });
  res.json(messages);
});
